export function createCalculator() {
    let currentValue = 0;
    let memory = 0;

    const calculator = {
        add(n) {
            currentValue += n;
            return this;
        },
        subtract(n) {
            currentValue -= n;
            return this;
        },
        multiply(n) {
            currentValue *= n;
            return this;
        },
        divide(n) {
            if (n === 0) {
                // Handle division by zero gracefully if possible, though standard behavior usually results in Infinity/NaN.
                // For simplicity and robustness in a calculator context, we let JS handle it unless specified otherwise.
                currentValue /= n;
            } else {
                currentValue /= n;
            }
            return this;
        },
        clear() {
            currentValue = 0;
            return this;
        },
        result() {
            return currentValue;
        },
        memoryStore() {
            memory = currentValue;
            return this;
        },
        memoryAdd() {
            memory += currentValue;
            return this;
        },
        memoryClear() {
            memory = 0;
            return this;
        },
        memoryRecall() {
            return memory;
        }
    };

    return calculator;
}

export interface Calculator {
  add(n: number): Calculator
  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
