class CalculatorImpl implements Calculator {
  private currentValue: number;
  private memory: number;

  constructor() {
    this.currentValue = 0;
    this.memory = 0;
  }

  add(n: number): CalculatorImpl {
    this.currentValue += n;
    return this;
  }

  subtract(n: number): CalculatorImpl {
    this.currentValue -= n;
    return this;
  }

  multiply(n: number): CalculatorImpl {
    this.currentValue *= n;
    return this;
  }

  divide(n: number): CalculatorImpl {
    if (n === 0) {
      // Handle division by zero gracefully, though typically results might be NaN or Infinity
      // For simplicity in this context, we assume standard number handling.
      this.currentValue = Number(isNaN(this.currentValue / n) ? this.currentValue : this.currentValue / n);
    } else {
      this.currentValue /= n;
    }
    return this;
  }

  clear(): CalculatorImpl {
    this.currentValue = 0;
    // Memory remains independent
    return this;
  }

  result(): number {
    return this.currentValue;
  }

  memoryStore(): CalculatorImpl {
    this.memory = this.currentValue;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): CalculatorImpl {
    this.memory = 0;
    return this;
  }

  memoryAdd(): CalculatorImpl {
    this.memory += this.currentValue;
    return this;
  }
}

export function createCalculator(): CalculatorImpl {
  return new CalculatorImpl();
}

