interface RateLimiterState {
  windowStart: number;
  count: number;
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;
  const storage = new Map<string, RateLimiterState>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = storage.get(key);

      if (!state || nowMs >= state.windowStart + WINDOW_MS) {
        state = { windowStart: nowMs, count: 0 };
        storage.set(key, state);
      }

      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }

      return false;
    },
    remaining(key: string, nowMs: number): number {
      const state = storage.get(key);

      if (!state) {
        return MAX_REQUESTS;
      }

      if (nowMs >= state.windowStart + WINDOW_MS) {
        return MAX_REQUESTS;
      }

      return Math.max(0, MAX_REQUESTS - state.count);
    },
    reset(key: string): void {
      storage.delete(key);
    },
  };
}

