      const duration = ttlMs ?? defaultTtl;
      const expiresAt = nowMs + duration;
      entries.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = entries.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key, nowMs) {
      const entry = entries.get(key);
      if (!entry) {
        return false;
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return false;
      }
      return true;
    },
    delete(key) {
      if (entries.has(key)) {
        entries.delete(key);
        return true;
      }
      return false;
    },
    size(nowMs) {
      let count = 0;
      for (const entry of entries.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      entries.clear();
    }
  };
}

