export function createEventEmitter() {
  type EventKey = string | symbol;
  type Listener = (payload: any) => any;
  interface Entry {
    fn: Listener;
    once: boolean;
  }

  const eventMap = new Map<EventKey, Entry[]>();

  const on = (event: EventKey, listener: Listener): number => {
    const arr = eventMap.get(event) ?? [];
    arr.push({ fn: listener, once: false });
    eventMap.set(event, arr);
    return arr.length;
  };

  const once = (event: EventKey, listener: Listener): number => {
    const arr = eventMap.get(event) ?? [];
    arr.push({ fn: listener, once: true });
    eventMap.set(event, arr);
    return arr.length;
  };

  const off = (event: EventKey, listener: Listener): boolean => {
    const arr = eventMap.get(event);
    if (!arr) return false;
    const idx = arr.findIndex((e) => e.fn === listener);
    if (idx === -1) return false;
    arr.splice(idx, 1);
    if (arr.length === 0) {
      eventMap.delete(event);
    } else {
      eventMap.set(event, arr);
    }
    return true;
  };

  const emit = (event: EventKey, payload: any): any[] => {
    const original = eventMap.get(event);
    if (!original) return [];
    const results: any[] = [];
    // Iterate over a snapshot to avoid calling new listeners added during emit
    for (const entry of [...original]) {
      results.push(entry.fn(payload));
      if (entry.once) {
        const arr = eventMap.get(event);
        if (arr) {
          const idx = arr.indexOf(entry);
          if (idx !== -1) {
            arr.splice(idx, 1);
          }
          if (arr.length === 0) {
            eventMap.delete(event);
          } else {
            eventMap.set(event, arr);
          }
        }
      }
    }
    return results;
  };

  const listenerCount = (event: EventKey): number => {
    return eventMap.get(event)?.length ?? 0;
  };

  return { on, once, off, emit, listenerCount };
}

export type Listener = (payload: unknown) => unknown

export interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  type Wrapper = { listener: Listener; once: boolean }

  class Emitter implements EventEmitter {
    private _events = new Map<string, Wrapper[]>()

    on(event: string, listener: Listener): number {
      const list = this._events.get(event) ?? []
      list.push({ listener, once: false })
      this._events.set(event, list)
      return list.length
    }

    once(event: string, listener: Listener): number {
      const list = this._events.get(event) ?? []
      list.push({ listener, once: true })
      this._events.set(event, list)
      return list.length
    }

    off(event: string, listener: Listener): boolean {
      const list = this._events.get(event)
      if (!list) return false
      const idx = list.findIndex(w => w.listener === listener)
      if (idx === -1) return false
      list.splice(idx, 1)
      if (list.length === 0) this._events.delete(event)
      return true
    }

    emit(event: string, payload: unknown): unknown[] {
      const list = this._events.get(event)
      if (!list) return []
      const results: unknown[] = []
      for (let i = 0; i < list.length; i++) {
        const wrapper = list[i]
        results.push(wrapper.listener(payload))
        if (wrapper.once) {
          list.splice(i, 1)
          i--
        }
      }
      if (list.length === 0) this._events.delete(event)
      return results
    }

    listenerCount(event: string): number {
      const list = this._events.get(event)
      return list ? list.length : 0
    }
  }

  return new Emitter()
}

export function createRateLimiter() {
  const data = new Map<string, { windowStart: number; count: number }>();
  const LIMIT = 3;
  const WINDOW_MS = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      const state = data.get(key);
      if (!state || nowMs >= state.windowStart + WINDOW_MS) {
        // start a new window
        data.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }
      if (state.count < LIMIT) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = data.get(key);
      if (!state || nowMs >= state.windowStart + WINDOW_MS) {
        // fresh window, all slots available
        return LIMIT;
      }
      const remaining = LIMIT - state.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key: string): void {
      data.delete(key);
    },
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<string, { windowStart: number; count: number }>()

  function getEntry(key: string, nowMs: number) {
    let entry = state.get(key)
    if (!entry) {
      entry = { windowStart: nowMs, count: 0 }
      state.set(key, entry)
    } else if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs
      entry.count = 0
    }
    return entry
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = getEntry(key, nowMs)
      if (entry.count < limit) {
        entry.count++
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      const entry = getEntry(key, nowMs)
      const remaining = limit - entry.count
      return remaining > 0 ? remaining : 0
    },

    reset(key: string): void {
      state.delete(key)
    },
  }
}

