export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  function set(
    key: string,
    value: unknown,
    nowMs: number,
    ttlMs?: number
  ): void {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    store.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const entry = store.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = store.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  }

  function deleteKey(key: string): boolean {
    return store.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const [key, entry] of store.entries()) {
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
      } else {
        count++;
      }
    }
    return count;
  }

  function clear(): void {
    store.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}

export function createTtlCache(): TtlCache {
  const DEFAULT_TTL = 1000;
  const map = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      const expiresAt = nowMs + (ttlMs ?? DEFAULT_TTL);
      map.set(key, { value, expiresAt });
    },

    get(key, nowMs) {
      const entry = map.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key, nowMs) {
      const entry = map.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return false;
      }
      return true;
    },

    delete(key) {
      return map.delete(key);
    },

    size(nowMs) {
      let count = 0;
      for (const [k, entry] of map.entries()) {
        if (nowMs >= entry.expiresAt) {
          map.delete(k);
        } else {
          count++;
        }
      }
      return count;
    },

    clear() {
      map.clear();
    },
  };
}

