export function createRateLimiter() {
  const WINDOW_SIZE = 1000;
  const MAX_REQUESTS = 3;
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const record = state.get(key);

      if (!record || nowMs - record.windowStart >= WINDOW_SIZE) {
        state.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }

      if (record.count < MAX_REQUESTS) {
        record.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const record = state.get(key);

      if (!record || nowMs - record.windowStart >= WINDOW_SIZE) {
        return MAX_REQUESTS;
      }

      return Math.max(0, MAX_REQUESTS - record.count);
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}

