type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

class EventEmitterImpl implements EventEmitter {
  private listeners = new Map<string, Listener[]>();

  on(event: string, listener: Listener): number {
    let arr = this.listeners.get(event);
    if (!arr) {
      arr = [];
      this.listeners.set(event, arr);
    }
    arr.push(listener);
    return arr.length;
  }

  once(event: string, listener: Listener): number {
    const wrapper: Listener = (payload) => {
      listener(payload);
      this.off(event, wrapper);
    };
    let arr = this.listeners.get(event);
    if (!arr) {
      arr = [];
      this.listeners.set(event, arr);
    }
    arr.push(wrapper);
    return arr.length;
  }

  off(event: string, listener: Listener): boolean {
    const arr = this.listeners.get(event);
    if (!arr) return false;
    const idx = arr.indexOf(listener);
    if (idx === -1) return false;
    arr.splice(idx, 1);
    if (arr.length === 0) {
      this.listeners.delete(event);
    }
    return true;
  }

  emit(event: string, payload: unknown): unknown[] {
    const arr = this.listeners.get(event);
    if (!arr) return [];
    const results: unknown[] = [];
    const snapshot = arr.slice();
    for (const listener of snapshot) {
      const ret = listener(payload);
      results.push(ret);
    }
    return results;
  }

  listenerCount(event: string): number {
    const arr = this.listeners.get(event);
    return arr ? arr.length : 0;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitterImpl();
}

