export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  class TtlCacheImpl implements TtlCache {
    private entries: Map<string, {value: unknown; expiresAt: number}> = new Map();

    private defaultTtlMs = 1000;

    private currentNow(): number {
      // use Date.now() as fallback; will be used in delete only
      return Date.now();
    }

    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs !== undefined ? ttlMs : this.defaultTtlMs;
      // When ttl is 0, treat as immediate expiration (expiresAt = nowMs)
      const expiresAt = ttl === 0 ? nowMs : nowMs + ttl;
      this.entries.set(key, { value, expiresAt });
    }

    get(key: string, nowMs: number): unknown {
      const entry = this.entries.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        this.entries.delete(key);
        return undefined;
      }
      return entry.value;
    }

    has(key: string, nowMs: number): boolean {
      const entry = this.entries.get(key);
      if (!entry) return false;
      return nowMs < entry.expiresAt;
    }

    delete(key: string): boolean {
      const entry = this.entries.get(key);
      const now = this.currentNow();
      if (!entry) return false;
      if (now >= entry.expiresAt) {
        // already expired, treat as not present
        this.entries.delete(key);
        return false;
      }
      this.entries.delete(key);
      return true;
    }

    size(nowMs: number): number {
      let count = 0;
      for (const entry of this.entries.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    }

    clear(): void {
      this.entries.clear();
    }
  }

  return new TtlCacheImpl();
}
