type Listener = (payload: any) => any;

interface ListenerEntry {
  fn: Listener;
  once: boolean;
}

export function createEventEmitter() {
  const listeners = new Map<string, ListenerEntry[]>();

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const list = listeners.get(event)!;
      list.push({ fn: listener, once: false });
      return list.length;
    },
    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const list = listeners.get(event)!;
      list.push({ fn: listener, once: true });
      return list.length;
    },
    off(event, listener) {
      const list = listeners.get(event);
      if (!list) return false;
      const index = list.findIndex(entry => entry.fn === listener);
      if (index === -1) return false;
      list.splice(index, 1);
      if (list.length === 0) {
        listeners.delete(event);
      }
      return true;
    },
    emit(event, payload) {
      const list = listeners.get(event);
      if (!list) return [];
      const results: any[] = [];
      const snapshot = list.slice();

      for (const entry of snapshot) {
        results.push(entry.fn(payload));
      }

      const toRemove = snapshot.filter(entry => entry.once);
      if (toRemove.length > 0) {
        const remaining = list.filter(entry => !toRemove.includes(entry));
        if (remaining.length === 0) {
          listeners.delete(event);
        } else if (remaining.length !== list.length) {
          listeners.set(event, remaining);
        }
      }

      return results;
    },
    listenerCount(event) {
      return listeners.has(event) ? listeners.get(event)!.length : 0;
    }
  };
}

export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_SIZE_MS = 1000;
  const storage = new Map<string, { windowStartMs: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const state = storage.get(key);
      const isNewWindow = !state || nowMs >= state.windowStartMs + WINDOW_SIZE_MS;

      if (isNewWindow) {
        storage.set(key, { windowStartMs: nowMs, count: 0 });
      }

      const currentState = storage.get(key);
      if (!currentState) {
        return false;
      }

      if (currentState.count < MAX_REQUESTS) {
        currentState.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = storage.get(key);
      if (!state) {
        return MAX_REQUESTS;
      }

      if (nowMs >= state.windowStartMs + WINDOW_SIZE_MS) {
        return MAX_REQUESTS;
      }

      const remaining = MAX_REQUESTS - state.count;
      return remaining < 0 ? 0 : remaining;
    },

    reset(key: string): void {
      storage.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const LIMIT = 3;
const WINDOW_MS = 1000;

interface State {
  count: number;
  windowStart: number;
}

export function createRateLimiter(): RateLimiter {
  const store = new Map<string, State>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = store.get(key);
      if (!state) {
        state = { count: 0, windowStart: nowMs };
        store.set(key, state);
      } else {
        if (nowMs - state.windowStart >= WINDOW_MS) {
          state.count = 0;
          state.windowStart = nowMs;
        }
      }

      if (state.count < LIMIT) {
        state.count++;
        return true;
      }

      return false;
    },
    remaining(key: string, nowMs: number): number {
      let state = store.get(key);
      if (!state) {
        state = { count: 0, windowStart: nowMs };
        store.set(key, state);
      } else {
        if (nowMs - state.windowStart >= WINDOW_MS) {
          state.count = 0;
          state.windowStart = nowMs;
        }
      }

      return LIMIT - state.count;
    },
    reset(key: string): void {
      store.delete(key);
    },
  };
}

