    listPending(): Todo[] {
      return Array.from(todos.values()).filter((t) => !t.completed);
    },
    clearCompleted(): void {
      const idsToDelete: number[] = [];
      for (const [id, todo] of todos) {
        if (todo.completed) {
          idsToDelete.push(id);
        }
      }
      for (const id of idsToDelete) {
        todos.delete(id);
      }
    },
  };
