type Listener = (payload: any) => any;

interface EventRegistry {
    normal: Array<Listener>;
    once: Array<Listener>;
}

/**
 * Factory that creates a minimal EventEmitter interface.
 *
 * @returns {object} An event emitter object with on, once, off, emit, and listenerCount methods.
 */
export const createEventEmitter = (): ReturnType<typeof createEventEmitter> => {
    const listeners: Map<string, EventRegistry> = new Map();

    const getRegistry = (event: string): EventRegistry => {
        if (!listeners.has(event)) {
            listeners.set(event, { normal: [], once: [] });
        }
        return listeners.get(event)!;
    };

    /**
     * Registers a normal listener.
     * @param event The event name.
     * @param listener The function to call when the event is emitted.
     * @returns The new listener count for the event.
     */
    const on = (event: string, listener: Listener): number => {
        const registry = getRegistry(event);
        registry.normal.push(listener);
        return registry.normal.length + registry.once.length;
    };

    /**
     * Registers a listener that will be automatically removed after the first emission.
     * @param event The event name.
     * @param listener The function to call when the event is emitted.
     * @returns The new listener count for the event.
     */
    const once = (event: string, listener: Listener): number => {
        const registry = getRegistry(event);
        registry.once.push(listener);
        return registry.normal.length + registry.once.length;
    };

    /**
     * Removes a single matching listener for an event.
     * @param event The event name.
     * @param listener The listener function to remove.
     * @returns true if a listener was removed, false otherwise.
     */
    const off = (event: string, listener: Listener): boolean => {
        const registry = listeners.get(event);
        if (!registry) {
            return false;
        }

        // Try to remove from normal listeners first
        for (let i = 0; i < registry.normal.length; i++) {
            if (registry.normal[i] === listener) {
                registry.normal.splice(i, 1);
                return true;
            }
        }

        // If not found, try to remove from once listeners
        for (let i = 0; i < registry.once.length; i++) {
            if (registry.once[i] === listener) {
                registry.once.splice(i, 1);
                return true;
            }
        }

        return false;
    };

    /**
     * Emits an event, calling all registered listeners.
     * @param event The event name.
     * @param payload The payload to pass to listeners.
     * @returns An array containing the return value of every listener call, in order.
     */
    const emit = (event: string, payload?: any): Function[] => {
        const registry = listeners.get(event);
        if (!registry) {
            return [];
        }

        const results: Function[] = [];
        const listenersToFire: Listener[] = [...registry.normal];
        const onceListenersToFire: Listener[] = [...registry.once];

        // 1. Fire Normal Listeners
        listenersToFire.forEach(listener => {
            try {
                const result = listener(payload);
                results.push(result);
            } catch (e) {
                // In a real scenario, we might log this, but here we just track execution.
                results.push(e);
            }
        });

        // 2. Fire One-Time Listeners and Clean Up
        const firedOnceIndices: number[] = [];
        onceListenersToFire.forEach((listener, index) => {
            try {
                const result = listener(payload);
                results.push(result);
                firedOnceIndices.push(index);
            } catch (e) {
                results.push(e);
                firedOnceIndices.push(index);
            }
        });

        // Remove fired 'once' listeners *in reverse order* to maintain correct indices during mutation
        firedOnceIndices.sort((a, b) => b - a).forEach(index => {
            registry.once.splice(index, 1);
        });

        return results;
    };

    /**
     * Returns the current number of registered listeners for an event.
     * @param event The event name.
     * @returns The total listener count.
     */
    const listenerCount = (event: string): number => {
        const registry = listeners.get(event);
        return registry ? (registry.normal.length + registry.once.length) : 0;
    };

    return {
        on,
        once,
        off,
        emit,
        listenerCount,
    };
};
