            const listenersToProcess = [...state.listeners];
            let listenersRemovedDuringDispatch = 0;

            for (let i = 0; i < listenersToProcess.length; i++) {
                const entry = listenersToProcess[i];

                try {
                    const result = entry.listener(payload);
                    results.push(result);

                    // Handle removal for 'once' listeners immediately after invocation
                    if (entry.isOnce) {
                        // Re-check if this entry is still in the main list before removing it
                        // This prevents race conditions if multiple internal parts call emit on the same event.
                        const indexInMainList = state.listeners.findIndex(e => e.id === entry.id);
                        if (indexInMainList !== -1) {
                            state.listeners.splice(indexInMainList, 1);
                            state.count -= 1;
                            // Since we found and removed a listener, we signal removal to prevent re-processing, 
                            // although in this loop structure it's mostly for conceptual clarity.
                            listenersRemovedDuringDispatch++;
                        }
                        // Decrementing the count here is crucial for correct state management.
                    }
                } catch (e) {
                    // In a real scenario, we might want more advanced error handling, 
                    // but for this contract fulfillment, we just let the error propagate up 
                    // through the function call stack, or optionally capture it if 'unknown' needs to handle Errors.
                    // Since the return type is unknown[], we just skip pushing the error to results 
                    // if we assume the caller handles the exception.
                }
            }

            // Handle the case where emission logic might have removed multiple listeners in one go, 
            // ensuring the count accurately reflects removals.
            // The count update inside the loop handles removal, so just returning results is enough.

            return results;
        },

        /**
         * Returns the number of listeners registered for the event.
         * @returns The listener count.
         */
        listenerCount: (event: string): number => {
            const state = listenersMap.get(event);
            return state ? state.count : 0;
        }
    };

    return eventEmitterApi;
}
