interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

// Internal state structure for a key
type KeyState = {
  windowStartMs: number;
  count: number;
};

/**
 * Creates a rate limiter instance using a fixed window policy.
 * @returns {RateLimiter} An object implementing the rate limiting interface.
 */
export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  const stores = new Map<string, KeyState>();

  /**
   * Helper function to get and potentially reset the state for a key based on the current time.
   * @param key The key defining the scope.
   * @param nowMs Current time in milliseconds.
   * @returns {KeyState} The current or reset key state.
   */
  const updateWindowState = (key: string, nowMs: number): KeyState => {
    const existingState = stores.get(key);

    let state: KeyState;

    // Check for window reset condition
    const windowExpired = existingState 
      ? (nowMs - existingState.windowStartMs) >= WINDOW_MS 
      : true; // Treat first access as expired/fresh

    if (windowExpired) {
      state = { windowStartMs: nowMs, count: 1 };
      stores.set(key, state);
    } else {
      state = existingState;
    }
    return state;
  };
  // NOTE: For tracking sequential calls correctly within the module context,
  // we must adjust the state *before* determining success/failure in allow().

  /**
   * Checks if a request for a given key should be allowed.
   * @param key The unique identifier for the request.
   * @param nowMs Current time in milliseconds.
   * @returns {boolean} True if the request is allowed, false otherwise.
   */
  const allow = (key: string, nowMs: number): boolean => {
    let state = stores.get(key);

    // 1. Check for window reset if state exists
    const windowExpired = state 
      ? (nowMs - state.windowStartMs) >= WINDOW_MS 
      : true;

    let currentCount: number;
    let newWindowStarted = false;

    if (windowExpired) {
      // Window reset: Start new window
      currentCount = 1;
      stores.set(key, { windowStartMs: nowMs, count: 1 });
      newWindowStarted = true;
    } else {
      // Window active: Use existing count
      currentCount = state.count + 1;
    }

    // 2. Check limit
    const allowed = currentCount <= LIMIT;

    if (allowed && !newWindowStarted) {
       // Only update stored count if the window wasn't just reset by this call, 
       // but the window continues, otherwise the increment happened above.
       // To simplify, we always update the count based on the successful call logic
       stores.set(key, { windowStartMs: (windowExpired ? nowMs : state.windowStartMs), count: currentCount });
    }

    // Re-evaluating state management for simplicity and correctness:
    // Let's always read the state, check for reset, and then decide the next count.

    // Re-implementing the core logic to keep state manipulation atomic per access/check
    let stateAfterCheck = stores.get(key);

    if (!stateAfterCheck || (nowMs - stateAfterCheck.windowStartMs) >= WINDOW_MS) {
      // Window Reset
      if (LIMIT < 1) return false; // Safety check for impossible limit
      stores.set(key, { windowStartMs: nowMs, count: 1 });
      return true;
    } else {
      // Window Active
      const newCount = stateAfterCheck.count + 1;
      if (newCount <= LIMIT) {
        stores.set(key, { windowStartMs: stateAfterCheck.windowStartMs, count: newCount });
        return true;
      } else {
        return false;
      }
    }
  };

  /**
   * Returns the remaining number of requests for the key in the current window.
   * @param key The unique identifier for the request.
   * @param nowMs Current time in milliseconds.
   * @returns {number} The remaining quota (clamped at 0).
   */
  const remaining = (key: string, nowMs: number): number => {
    let state = stores.get(key);

    const windowExpired = !state || (nowMs - state.windowStartMs) >= WINDOW_MS;

    if (windowExpired) {
      // If window expired, remaining is limit, but we don't modify state here.
      return LIMIT;
    }

    const currentRemaining = Math.max(0, LIMIT - state.count);
    return currentRemaining;
  };

  /**
   * Removes the state for a specific key, effectively resetting the rate limit counter.
   * @param key The unique identifier for the request.
   */
  const reset = (key: string): void => {
    stores.delete(key);
  };

  return {
    allow,
    remaining,
    reset,
  };
}
