        completed: boolean;
    }

    interface TodoApp {
        addTodo(text: string): Todo;
        getTodo(id: number): Todo | undefined;
        toggleTodo(id: number): void;
        deleteTodo(id: number): boolean;
        listTodos(): Todo[];
        listCompleted(): Todo[];
        listPending(): Todo[];
        clearCompleted(): void;
    }

    // State encapsulated within the closure
    let todos: Todo[] = [];
    let nextId: number = 0;

    /**
     * Adds a new todo item.
     * @param text The text content of the todo.
     * @returns The newly created Todo object.
     */
    const addTodo = (text: string): Todo => {
        if (!text || text.trim() === "") {
            // In a real system, this might throw or return null, but adhering to type contract assumes valid input for addition or handles gracefully.
            return { id: nextId++, text: "Empty Text Placeholder", completed: false }; // Minimal safe return if empty text is possible input
        }
        const newTodo: Todo = {
            id: nextId++,
            text: text.trim(),
            completed: false,
        };
        todos.push(newTodo);
        return newTodo;
    };

    /**
     * Retrieves a todo by its ID.
     * @param id The ID of the todo to retrieve.
     * @returns The Todo object or undefined if not found.
     */
    const getTodo = (id: number): Todo | undefined => {
        return todos.find(todo => todo.id === id);
    };

    /**
     * Toggles the completion status of a todo. Does nothing if the ID is not found.
     * @param id The ID of the todo to toggle.
     */
    const toggleTodo = (id: number): void => {
        const todo = getTodo(id);
        if (todo) {
            todo.completed = !todo.completed;
        }
    };

    /**
     * Deletes a todo by its ID.
     * @param id The ID of the todo to delete.
     * @returns True if the todo was found and deleted, false otherwise.
     */
    const deleteTodo = (id: number): boolean => {
        const initialLength = todos.length;
        // Filter creates a new array, effectively deleting the item while retaining the ID's integrity in the system's history,
        // but removing the item from the active state list.
        todos = todos.filter(todo => todo.id !== id);
        return todos.length < initialLength;
    };

    /**
     * Returns an array of all todos.
     * @returns A copy of the current todos array.
     */
    const listTodos = (): Todo[] => {
        // Return a shallow copy to prevent external mutation of the internal state
        return [...todos];
    };

    /**
     * Returns an array of all completed todos.
     * @returns A copy of the completed todos array.
     */
    const listCompleted = (): Todo[] => {
        return todos.filter(todo => todo.completed);
    };

    /**
     * Returns an array of all pending todos.
     * @returns A copy of the pending todos array.
     */
    const listPending = (): Todo[] => {
        return todos.filter(todo => !todo.completed);
    };

    /**
     * Removes all todos marked as completed from the state.
     */
    const clearCompleted = (): void => {
        // Filter creates a new array with only the non-completed items, satisfying the non-mutation requirement.
        todos = todos.filter(todo => !todo.completed);
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
