export function createCalculator(): {
    add(n: number): Calculator;
    subtract(n: number): Calculator;
    multiply(n: number): Calculator;
    divide(n: number): Calculator;
    clear(): Calculator;
    result(): number;
    memoryStore(): Calculator;
    memoryAdd(): Calculator;
    memoryClear(): Calculator;
    memoryRecall(): number;
} {
    class Calculator {
        private currentValue: number = 0;
        private memory: number = 0;

        add(n: number): Calculator {
            this.currentValue += n;
            return this;
        }

        subtract(n: number): Calculator {
            this.currentValue -= n;
            return this;
        }

        multiply(n: number): Calculator {
            this.currentValue *= n;
            return this;
        }

        divide(n: number): Calculator {
            if (n === 0) {
                // In a real application, this would throw an error. For this contract, we handle it simply.
                // Assuming standard JS behavior for division by zero if not explicitly restricted.
                this.currentValue = Infinity; 
            } else {
                this.currentValue /= n;
            }
            return this;
        }

        clear(): Calculator {
            this.currentValue = 0;
            return this;
        }

        result(): number {
