export function createCalculator(): Calculator {
  const calculator: Calculator = {
    current: 0,
    memory: 0,
    add(n: number): Calculator {
      this.current += n;
      return this;
    },
    subtract(n: number): Calculator {
      this.current -= n;
      return this;
    },
    multiply(n: number): Calculator {
      this.current *= n;
      return this;
    },
    divide(n: number): Calculator {
      if (n === 0) {
        // Handle division by zero, for robustness, though behavior isn't strictly defined for errors.
        // We will maintain the current value or throw/return specific state if necessary.
        // For this implementation, we'll allow it to result in Infinity/NaN if standard JS behavior is followed.
        this.current = Number(this.current / n);
      } else {
        this.current = this.current / n;
      }
      return this;
    },
    clear(): Calculator {
      this.current = 0;
      // Memory is independent, so it remains unchanged.
      return this;
    },
    result(): number {
      return this.current;
    },
    memoryStore(): Calculator {
      // Store current value into memory
      this.memory += this.current;
      return this;
    },
    memoryRecall(): number {
      // Return memory, does not mutate current value
      return this.memory;
    },
    memoryClear(): Calculator {
      this.memory = 0;
      return this;
    },
    memoryAdd(): Calculator {
      // Adds current value into memory and does NOT change current value
      this.memory += this.current;
      return this;
    }
  };

  return calculator;
}

