export function createEventEmitter(): {
    on: (event: string, listener: (...args: any[]) => any) => number;
    once: (event: string, listener: (...args: any[]) => any) => number;
    off: (event: string, listener: (...args: any[]) => any) => boolean;
    emit: (event: string, ...args: any[]) => any;
    listenerCount: (event: string) => number;
} {
    const eventListeners: { [eventName: string]: { listeners: { listener: (...args: any[]) => any, isOnce: boolean }[] } } = {};

    const on = (event: string, listener: (...args: any[]) => any): number => {
        if (!eventListeners[event]) {
            eventListeners[event] = { listeners: [] };
        }
        eventListeners[event].listeners.push({ listener, isOnce: false });
        return eventListeners[event].listeners.length;
    };

    const once = (event: string, listener: (...args: any[]) => any): number => {
        if (!eventListeners[event]) {
            eventListeners[event] = { listeners: [] };
        }
        eventListeners[event].listeners.push({ listener, isOnce: true });
        return eventListeners[event].listeners.length;
    };

    const off = (event: string, listener: (...args: any[]) => any): boolean => {
        if (!eventListeners[event]) {
            return false;
        }

        const listeners = eventListeners[event].listeners;
        const initialLength = listeners.length;

        // Filter out the listener to be removed. Since listeners are stored as objects,
        // we need to compare the actual function reference.
        const newListeners = listeners.filter(item => item.listener !== listener);

        if (newListeners.length < initialLength) {
            eventListeners[event].listeners = newListeners;
            return true;
        }

        return false;
    };

    const listenerCount = (event: string): number => {
        return eventListeners[event]?.listeners?.length ?? 0;
    };

    const emit = (event: string, ...args: any[]): any => {
        const listeners = eventListeners[event]?.listeners || [];
        const results: any[] = [];

        for (const item of listeners) {
            if (item.isOnce) {
                results.push(item.listener(...args));
                // Remove one-time listener after firing
                eventListeners[event].listeners = eventListeners[event].listeners.filter(l => l !== item);
                break; // Stop processing further listeners if this one was once
            } else {
                results.push(item.listener(...args));
            }
        }

        return results;
    };

    return {
        on,
        once,
        off,
        emit,
        listenerCount
    };
}
