export function createEventEmitter(): EventEmitter {
  type Listener = (payload: unknown) => unknown;

  interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
  }

  // Internal storage: Map<eventName, { regular: Listener[], once: Listener[] }>
  const eventListeners = new Map<string, { regular: Listener[], once: Listener[] }>();

  /**
   * Internal helper to get or create the listener structure for an event.
   * @param event The event name.
   * @returns The listener structure for that event.
   */
  function getEventListeners(event: string): { regular: Listener[], once: Listener[] } {
    if (!eventListeners.has(event)) {
      eventListeners.set(event, { regular: [], once: [] });
    }
    return eventListeners.get(event)!;
  }

  /**
   * Registers a regular listener.
   */
  function on(event: string, listener: Listener): number {
    const listeners = getEventListeners(event);
    listeners.regular.push(listener);
    return listeners.regular.length;
  }

  /**
   * Registers a one-time listener.
   */
  function once(event: string, listener: Listener): number {
    const listeners = getEventListeners(event);
    listeners.once.push(listener);
    return listeners.once.length;
  }

  /**
   * Removes a listener from a specific list.
   * @param event The event name.
   * @param listener The listener function to remove.
   * @returns true if the listener was found and removed, false otherwise.
   */
  function off(event: string, listener: Listener): boolean {
    const listeners = eventListeners.get(event);
    if (!listeners) {
      return false;
    }

    // Check regular listeners
    const initialRegularCount = listeners.regular.length;
    listeners.regular = listeners.regular.filter(l => l !== listener);
    if (listeners.regular.length < initialRegularCount) {
      return true;
    }

    // Check once listeners
    const initialOnceCount = listeners.once.length;
    listeners.once = listeners.once.filter(l => l !== listener);
    if (listeners.once.length < initialOnceCount) {
      return true;
    }

    return false;
  }

  /**
   * Emits an event, notifying all registered listeners in order.
   */
  function emit(event: string, payload: unknown): unknown[] {
    const listeners = eventListeners.get(event);
    if (!listeners) {
      return [];
    }

    const results: unknown[] = [];

    // 1. Emit regular listeners
    for (const listener of listeners.regular) {
      try {
        const result = listener(payload);
        results.push(result);
      } catch (e) {
        // Silently skip errors for robust event emission, unless error handling is specified
      }
    }

    // 2. Emit one-time listeners (and remove them)
    for (const listener of listeners.once) {
      try {
        const result = listener(payload);
        results.push(result);
        // Remove the listener after first invocation
        listeners.once = listeners.once.filter(l => l !== listener);
      } catch (e) {
        // Silently skip errors for robust event emission
      }
    }

    return results;
  }

  /**
   * Returns the total count of listeners for a specific event.
   */
  function listenerCount(event: string): number {
    const listeners = eventListeners.get(event);
    if (!listeners) {
      return 0;
    }
    return listeners.regular.length + listeners.once.length;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}
