export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;

  const state: Record<string, { windowStart: number, remaining: number }> = {};

  const allow = (key: string, nowMs: number): boolean => {
    const windowStart = state[key]?.windowStart;
    const remaining = state[key]?.remaining ?? LIMIT;

    let nowWindowStart = windowStart;

    // Boundary reset rule: if nowMs - windowStart >= windowMs, start a fresh window for that key
    if (windowStart !== undefined && nowMs - windowStart >= WINDOW_MS) {
      nowWindowStart = nowMs;
      state[key] = {
        windowStart: nowWindowStart,
        remaining: LIMIT,
      };
    }

    // Check if the key exists, otherwise treat as a new key
    const keyState = state[key] || { windowStart: nowWindowStart, remaining: LIMIT };

    if (keyState.remaining > 0) {
      keyState.remaining--;
      state[key] = keyState;
      return true;
    }

    return false;
  };

  const remaining = (key: string, nowMs: number): number => {
    const keyState = state[key];
    if (!keyState) {
      return LIMIT;
    }

    const windowStart = keyState.windowStart;
    const nowWindowStart = (nowMs - (nowMs % WINDOW_MS)) + (windowStart % WINDOW_MS); // Normalize to window start for calculation, though boundary check is more important.

    // Re-evaluate window start based on current time and state to handle potential missed boundary checks if only remaining check is called.
    let effectiveWindowStart = windowStart;

    if (nowMs - windowStart >= WINDOW_MS) {
      effectiveWindowStart = nowMs;
    }

    // If the window has passed significantly, we should ideally let the caller handle a reset, but for a pure remaining query, we base it on the recorded state relative to 'nowMs'.
    // Since the system relies on 'allow' updating state correctly, we only need to calculate the remaining based on what's recorded.

    return keyState.remaining;
  };

  const reset = (key: string): void => {
    if (state[key]) {
      delete state[key];
    }
  };

  return {
    allow,
    remaining,
    reset,
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

