export function createTodoApp(): TodoApp {
  interface Todo {
    id: number
    text: string
    completed: boolean
  }

  interface TodoApp {
    addTodo(text: string): Todo
    getTodo(id: number): Todo | undefined
    toggleTodo(id: number): void
    deleteTodo(id: number): boolean
    listTodos(): Todo[]
    listCompleted(): Todo[]
    listPending(): Todo[]
    clearCompleted(): void
  }

  const todos: Record<number, Todo> = {};
  let nextId: number = 1;

  const addTodo = (text: string): Todo => {
    const newTodo: Todo = {
      id: nextId++,
      text: text,
      completed: false,
    };
    todos[newTodo.id] = newTodo;
    return newTodo;
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos[id];
  };

  const toggleTodo = (id: number): void => {
    const todo = todos[id];
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    if (todos[id]) {
      delete todos[id];
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => {
    return Object.values(todos);
  };

  const listCompleted = (): Todo[] => {
    return Object.values(todos).filter(todo => todo.completed);
  };

  const listPending = (): Todo[] => {
    return Object.values(todos).filter(todo => !todo.completed);
  };

  const clearCompleted = (): void => {
    const completedTodos = Object.values(todos).filter(todo => todo.completed);
    for (const todo of completedTodos) {
      delete todos[todo.id];
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { value: unknown, expiresAt: number }>();

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const ttl = ttlMs === undefined ? 1000 : ttlMs;
    const expiresAt = nowMs + ttl;
    cache.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key);
    if (entry === undefined) {
      return undefined;
    }
    if (nowMs < entry.expiresAt) {
      return entry.value;
    }
    // If expired, we might consider removing it on a 'get' operation if we want clean results,
    // but standard cache behavior is to report the stale value if it hasn't been explicitly cleaned.
    // For has/size/delete to work correctly, we must ensure expired items are handled.
    // For this specific contract, we return the value regardless of expiration status,
    // but rely on has() to check validity.
    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key);
    if (entry === undefined) {
      return false;
    }
    return nowMs < entry.expiresAt;
  };

  const deleteEntry = (key: string): boolean => {
    if (!cache.has(key)) {
      return false;
    }
    cache.delete(key);
    return true;
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const entry of cache.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear = (): void => {
    cache.clear();
  };

  return {
    set,
    get,
    has,
    delete: deleteEntry,
    size,
    clear,
  };
}

export function createTtlCache(): TtlCache {
  interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
    get(key: string, nowMs: number): unknown
    has(key: string, nowMs: number): boolean
    delete(key: string): boolean
    size(nowMs: number): number
    clear(): void
  }

  interface CacheEntry {
    value: unknown
    expiresAt: number
  }

  const defaultTtlMs = 1000
  const cacheData: Map<string, CacheEntry> = new Map()

  const cacheInstance: TtlCache = {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs === undefined ? defaultTtlMs : ttlMs
      const expiresAt = nowMs + ttl

      if (ttl <= 0) {
        // Immediate expiration if ttlMs is 0 or less
        cacheData.delete(key)
        return
      }

      cacheData.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = cacheData.get(key)
      if (!entry) {
        return undefined
      }
      if (nowMs >= entry.expiresAt) {
        // Entry expired, remove it (lazy expiration)
        cacheData.delete(key)
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = cacheData.get(key)
      if (!entry) {
        return false
      }
      if (nowMs >= entry.expiresAt) {
        // Entry expired, remove it
        cacheData.delete(key)
        return false
      }
      return true
    },

    delete(key: string): boolean {
      const wasDeleted = cacheData.delete(key)
      return wasDeleted
    },

    size(nowMs: number): number {
      let count = 0
      for (const [key, entry] of cacheData.entries()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },

    clear(): void {
      cacheData.clear()
    }
  }

  return cacheInstance
}

