      if (index !== -1) {
        onceListeners[event].splice(index, 1);
        return true;
      }
    }
    return false;
  }

  return {
    on(event: string, listener: Listener): number {
      let eventListeners = listeners[event];
      if (!eventListeners) {
        eventListeners = listeners[event] = [];
      }
      eventListeners.push(listener);
      return eventListeners.length;
    },

    once(event: string, listener: Listener): number {
      let eventOnceListeners = onceListeners[event];
      if (!eventOnceListeners) {
        eventOnceListeners = onceListeners[event] = [];
      }
      const wrapped = (...args: unknown[]) => {
        listener(...args);
        off(event, wrapped);
      };
      eventOnceListeners.push(wrapped);
      return eventOnceListeners.length;
    },

    off,

    emit(event: string, payload?: unknown): unknown[] {
      const results: unknown[] = [];
      const eventListeners = listeners[event] || [];
      const eventOnceListeners = onceListeners[event] || [];

      eventListeners.forEach(l => {
        const result = l(payload);
        results.push(result);
      });

      eventOnceListeners.forEach(l => {
        const result = l(payload);
        results.push(result);
      });

      return results;
    },

    listenerCount(event: string): number {
      let count = listeners[event] ? listeners[event].length : 0;
      count += onceListeners[event] ? onceListeners[event].length : 0;
      return count;
    }
  };
}

export { createEventEmitter };
