type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

type ListenerRegistration = {
  listener: Listener
  once: boolean
}

function createEventEmitter(): EventEmitter {
  const listeners: Map<string, ListenerRegistration[]> = new Map()

  function on(event: string, listener: Listener): number {
    const eventListeners = listeners.get(event) || []
    eventListeners.push({ listener, once: false })
    listeners.set(event, eventListeners)
    return eventListeners.length
  }

  function once(event: string, listener: Listener): number {
    const eventListeners = listeners.get(event) || []
    eventListeners.push({ listener, once: true })
    listeners.set(event, eventListeners)
    return eventListeners.length
  }

  function off(event: string, listener: Listener): boolean {
    const eventListeners = listeners.get(event)
    if (!eventListeners) {
      return false
    }

    const index = eventListeners.findIndex(reg => reg.listener === listener)
    if (index === -1) {
      return false
    }

    eventListeners.splice(index, 1)
    if (eventListeners.length === 0) {
      listeners.delete(event)
    } else {
      listeners.set(event, eventListeners)
    }
    return true
  }

  function emit(event: string, payload: unknown): unknown[] {
    const eventListeners = listeners.get(event)
    if (!eventListeners) {
      return []
    }

    const results: unknown[] = []
    const toRemove: number[] = []

    eventListeners.forEach((reg, index) => {
      const result = reg.listener(payload)
      results.push(result)
      if (reg.once) {
        toRemove.push(index)
      }
    })

    if (toRemove.length > 0) {
      toRemove.sort((a, b) => b - a)
      const filteredListeners: ListenerRegistration[] = []
      eventListeners.forEach((reg, index) => {
        if (!toRemove.includes(index)) {
          filteredListeners.push(reg)
        }
      })
      listeners.set(event, filteredListeners)
      if (filteredListeners.length === 0) {
        listeners.delete(event)
      }
    }

    return results
  }

  function listenerCount(event: string): number {
    const eventListeners = listeners.get(event)
    return eventListeners ? eventListeners.length : 0
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  }
}

export { createEventEmitter }
