type RateLimiter = {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
};

const MAX_REQUESTS = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const existing = state.get(key);
      const windowEnd = existing?.windowStart ? existing.windowStart + WINDOW_MS : nowMs;

      if (!existing || nowMs >= windowEnd) {
        state.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }

      if (existing.count < MAX_REQUESTS) {
        existing.count++;
      }

      return existing.count <= MAX_REQUESTS;
    },

    remaining(key: string, nowMs: number): number {
      const existing = state.get(key);
      const windowEnd = existing?.windowStart ? existing.windowStart + WINDOW_MS : nowMs;

      if (!existing || nowMs >= windowEnd) {
        return MAX_REQUESTS;
      }

      return Math.max(0, MAX_REQUESTS - existing.count);
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}
