interface State {
  windowStart: number
  count: number
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const stateMap = new Map<string, State>()

  function ensureState(key: string, nowMs: number): State {
    let state = stateMap.get(key)
    if (!state) {
      state = { windowStart: nowMs, count: 0 }
    } else if (nowMs - state.windowStart >= windowMs) {
      state = { windowStart: nowMs, count: 0 }
    }
    return state
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const state = ensureState(key, nowMs)
      if (state.count >= limit) {
        return false
      }
      state.count++
      return true
    },
    remaining(key: string, nowMs: number): number {
      const state = ensureState(key, nowMs)
      const used = state.count
      return Math.max(0, limit - used)
    },
    reset(key: string): void {
      stateMap.delete(key)
    }
  }
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
