export function createEventEmitter() {
  const events = new Map<
    string,
    { fn: (payload: any) => any; once: boolean }[]
  >();

  return {
    on(event: string, listener: (payload: any) => any): number {
      const list = events.get(event) ?? [];
      list.push({ fn: listener, once: false });
      events.set(event, list);
      return list.length;
    },

    once(event: string, listener: (payload: any) => any): number {
      const list = events.get(event) ?? [];
      list.push({ fn: listener, once: true });
      events.set(event, list);
      return list.length;
    },

    off(event: string, listener: (payload: any) => any): boolean {
      const list = events.get(event);
      if (!list) return false;
      const idx = list.findIndex((l) => l.fn === listener);
      if (idx === -1) return false;
      list.splice(idx, 1);
      if (list.length === 0) {
        events.delete(event);
      } else {
        events.set(event, list);
      }
      return true;
    },

    emit(event: string, payload: any): any[] {
      const list = events.get(event);
      if (!list) return [];
      const results: any[] = [];
      // Copy for safe iteration
      for (const l of [...list]) {
        results.push(l.fn(payload));
      }
      // Remove once listeners after execution
      events.set(
        event,
        list.filter((l) => !l.once)
      );
      return results;
    },

    listenerCount(event: string): number {
      const list = events.get(event);
      return list ? list.length : 0;
    },
  };
}

