export function createRateLimiter() {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  const state = new Map<string, { startMs: number; count: number }>();

  function normalize(key: string, nowMs: number) {
    let data = state.get(key);
    if (!data) {
      data = { startMs: nowMs, count: 0 };
      state.set(key, data);
    } else if (nowMs >= data.startMs + WINDOW_MS) {
      data.startMs = nowMs;
      data.count = 0;
    }
    return data;
  }

  return {
    allow(key: string, nowMs: number) {
      const data = normalize(key, nowMs);
      if (data.count < LIMIT) {
        data.count += 1;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number) {
      const data = state.get(key);
      if (!data) return LIMIT;
      // Apply boundary rule
      if (nowMs >= data.startMs + WINDOW_MS) {
        // Window has elapsed; fresh window
        return LIMIT;
      }
      return Math.max(0, LIMIT - data.count);
    },

    reset(key: string) {
      state.delete(key);
    },
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, { start: number; count: number }>();

  const getEntry = (key: string, nowMs: number) => {
    const entry = store.get(key);
    if (!entry || nowMs - entry.start >= windowMs) {
      const newEntry = { start: nowMs, count: 0 };
      store.set(key, newEntry);
      return newEntry;
    }
    return entry;
  };

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = getEntry(key, nowMs);
      if (entry.count < limit) {
        entry.count += 1;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = getEntry(key, nowMs);
      const remaining = limit - entry.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key: string): void {
      store.delete(key);
    },
  };
}

