      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex((t) => t.id === id);
      if (index === -1) return false;
      todos.splice(index, 1);
      return true;
    },

    listTodos(): Todo[] {
      return [...todos];
    },

    listCompleted(): Todo[] {
      return todos.filter((t) => t.completed);
    },

    listPending(): Todo[] {
      return todos.filter((t) => !t.completed);
    },

    clearCompleted(): void {
      todos = todos.filter((t) => !t.completed);
    },
  };
}

export function createTtlCache(): {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
} {
    const cache = new Map<string, { value: unknown; expiresAt: number }>();
    const DEFAULT_TTL_MS = 1000;

    const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
        const expiresAt = nowMs + (ttlMs ?? DEFAULT_TTL_MS);
        cache.set(key, { value, expiresAt });
    };

    const get = (key: string, nowMs: number): unknown => {
        const entry = cache.get(key);
        if (!entry) return undefined;
        if (nowMs >= entry.expiresAt) {
            cache.delete(key);
            return undefined;
        }
        return entry.value;
    };

    const has = (key: string, nowMs: number): boolean => {
        const entry = cache.get(key);
        if (!entry) return false;
        if (nowMs >= entry.expiresAt) {
            cache.delete(key);
            return false;
        }
        return true;
    };

    const del = (key: string): boolean => {
        return cache.delete(key);
    };

    const size = (nowMs: number): number => {
        let count = 0;
        for (const [key, entry] of cache.entries()) {
            if (nowMs < entry.expiresAt) {
                count++;
            } else {
                cache.delete(key);
            }
        }
        return count;
    };

    const clear = (): void => {
        cache.clear();
    };

    return { set, get, has, delete: del, size, clear };
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const storage = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL_MS = 1000;

  const cleanupIfExpired = (key: string, nowMs: number): boolean => {
    const entry = storage.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      storage.delete(key);
      return false;
    }
    return true;
  };

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs === undefined ? DEFAULT_TTL_MS : ttlMs;
      storage.set(key, { value, expiresAt: nowMs + ttl });
    },

    get(key, nowMs) {
      if (!cleanupIfExpired(key, nowMs)) return undefined;
      return storage.get(key)!.value;
    },

    has(key, nowMs) {
      return cleanupIfExpired(key, nowMs);
    },

    delete(key) {
      return storage.delete(key);
    },

    size(nowMs) {
      let count = 0;
      for (const key of Array.from(storage.keys())) {
        if (cleanupIfExpired(key, nowMs)) count++;
      }
      return count;
    },

    clear() {
      storage.clear();
    },
  };
}

