export type Listener<T = any> = (payload: T) => any;

export interface EventEmitter {
  on<T>(event: string, listener: Listener<T>): number;
  once<T>(event: string, listener: Listener<T>): number;
  off<T>(event: string, listener: Listener<T>): boolean;
  emit<T>(event: string, payload: T): any[];
  listenerCount<T>(event: string): number;
}

interface EventEntry {
  listener: Listener<any>;
  once: boolean;
}

export function createEventEmitter(): EventEmitter {
  const registry: Map<string, EventEntry[]> = new Map();

  return {
    on<T>(event: string, listener: Listener<T>): number {
      const listeners = registry.get(event) || [];
      listeners.push({ listener, once: false });
      registry.set(event, listeners);
      return listeners.length;
    },

    once<T>(event: string, listener: Listener<T>): number {
      const listeners = registry.get(event) || [];
      listeners.push({ listener, once: true });
      registry.set(event, listeners);
      return listeners.length;
    },

    off<T>(event: string, listener: Listener<T>): boolean {
      const listeners = registry.get(event);
      if (!listeners) return false;

      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].listener === listener) {
          listeners.splice(i, 1);
          if (listeners.length === 0) {
            registry.delete(event);
          }
          return true;
        }
      }
      return false;
    },

    emit<T>(event: string, payload: T): any[] {
      const listeners = registry.get(event);
      if (!listeners) return [];

      const results: any[] = [];
      // We iterate over a copy to prevent issues if listeners modify the registry during execution
      const snapshot = [...listeners];

      for (const entry of snapshot) {
        results.push(entry.listener(payload));

        if (entry.once) {
          // Remove the specific entry from the actual registry
          const currentListeners = registry.get(event);
          if (currentListeners) {
            const index = currentListeners.indexOf(entry);
            if (index !== -1) {
              currentListeners.splice(index, 1);
              if (currentListeners.length === 0) {
                registry.delete(event);
              }
            }
          }
        }
      }

      return results;
    },

    listenerCount<T>(event: string): number {
      return registry.get(event)?.length || 0;
    }
  };
}
