type RateLimiter = {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
};

type KeyState = {
  windowStart: number;
  count: number;
};

export function createRateLimiter(): RateLimiter {
  const states = new Map<string, KeyState>();
  const WINDOW_SIZE_MS = 1000;
  const MAX_REQUESTS = 3;

  const getOrCreateState = (key: string, nowMs: number): KeyState => {
    let state = states.get(key);
    if (!state || nowMs - state.windowStart >= WINDOW_SIZE_MS) {
      state = {
        windowStart: nowMs,
        count: 0,
      };
      states.set(key, state);
    }
    return state;
  };

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrCreateState(key, nowMs);
      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = states.get(key);
      if (!state || nowMs - state.windowStart >= WINDOW_SIZE_MS) {
        return MAX_REQUESTS;
      }
      return Math.max(0, MAX_REQUESTS - state.count);
    },

    reset(key: string): void {
      states.delete(key);
    },
  };
}
