        } else {
          // We can't delete during iteration of values() easily without breaking logic,
          // but strictly speaking size() just needs to count non-expired.
          // However, for correctness of the cache state, we'll rely on the fact 
          // that get/has will clean up later, or we'd need a more complex iterator.
        }
      }

      // More robust size implementation for the contract
      let validSize = 0;
      for (const [k, entry] of cache.entries()) {
        if (nowMs < entry.expiresAt) {
          validSize++;
        } else {
          cache.delete(k);
        }
      }
      return validSize;
    },

    clear(): void {
      cache.clear();
    }
  };
}
