export function createEventEmitter() {
    type Listener = (payload: any) => any;
    const listeners = new Map<string, Listener[]>();

    function create(event: string): Listener[] {
        if (!listeners.has(event)) {
            listeners.set(event, []);
        }
        return listeners.get(event)!;
    }

    function on(event: string, listener: Listener): number {
        const list = create(event);
        list.push(listener);
        return list.length;
    }

    function off(event: string, listener: Listener): boolean {
        const list = listeners.get(event);
        if (!list) return false;
        const idx = list.findIndex(l => l === listener);
        if (idx >= 0) {
            list.splice(idx, 1);
            if (list.length === 0) {
                listeners.delete(event);
            }
            return true;
        }
        return false;
    }

    function once(event: string, listener: Listener): number {
        function wrapper(payload: any) {
            off(event, wrapper);
            listener(payload);
        }
        const list = create(event);
        list.push(wrapper);
        return list.length;
    }

    function emit(event: string, payload: any): any[] {
        const list = listeners.get(event);
        if (!list) return [];
        const results: any[] = [];
        for (const fn of list) {
            const r = fn(payload);
            results.push(r);
        }
        return results;
    }

    function listenerCount(event: string): number {
        const list = listeners.get(event);
        return list ? list.length : 0;
    }

    return { on, once, off, emit, listenerCount };
}

type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  const getListeners = (event: string): Array<{ fn: Listener; once: boolean }> => {
    let arr = listeners.get(event);
    if (!arr) {
      arr = [];
      listeners.set(event, arr);
    }
    return arr;
  };

  const count = (event: string): number => {
    const arr = listeners.get(event);
    return arr ? arr.length : 0;
  };

  const off: (event: string, listener: Listener) => boolean = (event, listener) => {
    const arr = listeners.get(event);
    if (!arr) return false;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].fn === listener) {
        arr.splice(i, 1);
        return true;
      }
    }
    return false;
  };

  const emit: (event: string, payload: unknown) => unknown[] = (event, payload) => {
    const arr = listeners.get(event);
    if (!arr) return [];
    const results: unknown[] = [];
    for (let i = 0; i < arr.length; i++) {
      const { fn, once } = arr[i];
      const result = fn(payload);
      results.push(result);
      if (once) {
        arr.splice(i, 1);
        i--;
      }
    }
    return results;
  };

  return {
    on(event, listener) {
      const arr = getListeners(event);
      arr.push({ fn: listener, once: false });
      return count(event);
    },
    once(event, listener) {
      const arr = getListeners(event);
      arr.push({ fn: listener, once: true });
      return count(event);
    },
    off,
    emit,
    listenerCount: (event: string) => count(event),
  };
}

export function createRateLimiter() {
  const WINDOW_MS = 1000;
  const LIMIT = 3;
  const store = new Map<string, { lastWindow: number; count: number }>();

  const currentWindow = (nowMs: number): number => nowMs / WINDOW_MS | 0;

  return {
    allow(key: string, nowMs: number): boolean {
      const window = currentWindow(nowMs);
      const entry = store.get(key) ?? { lastWindow: -1, count: 0 };
      if (window !== entry.lastWindow) {
        entry.lastWindow = window;
        entry.count = 0;
      }
      if (entry.count < LIMIT) {
        entry.count += 1;
        store.set(key, entry);
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const window = currentWindow(nowMs);
      const entry = store.get(key);
      if (!entry) {
        return LIMIT;
      }
      const effectiveCount = entry.lastWindow === window ? entry.count : 0;
      let rem = LIMIT - effectiveCount;
      if (rem < 0) rem = 0;
      return rem;
    },

    reset(key: string) {
      store.delete(key);
    },
  };
}

