    todos.push(t);
    nextId++;
    return t;
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos.find(t => t.id === id);
  };

  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const idx = todos.findIndex(t => t.id === id);
    if (idx !== -1) {
      todos.splice(idx, 1);
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => {
    return [...todos];
  };

  const listCompleted = (): Todo[] => {
    return [...todos.filter(t => t.completed)];
  };

  const listPending = (): Todo[] => {
    return [...todos.filter(t => !t.completed)];
  };

  const clearCompleted = (): void => {
    for (let i = todos.length - 1; i >= 0; i--) {
      if (todos[i].completed) {
        todos.splice(i, 1);
      }
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

export function createTtlCache() {
  const store = new Map<string, {value: unknown; expiresAt: number}>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs ?? 1000;
      const expiresAt = nowMs + ttl;
      store.set(key, {value, expiresAt});
    },
    get(key: string, nowMs: number): unknown {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      return !!entry && nowMs < entry.expiresAt;
    },
    delete(key: string): boolean {
      const existed = store.has(key);
      if (existed) {
        store.delete(key);
      }
      return existed;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      store.clear();
    }
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs !== undefined ? ttlMs : 1000;
      const expiresAt = nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },

    get(key, nowMs) {
      const entry = cache.get(key);
      return entry && entry.expiresAt > nowMs ? entry.value : undefined;
    },

    has(key, nowMs) {
      const entry = cache.get(key);
      return entry && entry.expiresAt > nowMs;
    },

    delete(key) {
      return cache.delete(key);
    },

    size(nowMs) {
      let count = 0;
      for (const entry of cache.values()) {
        if (entry.expiresAt > nowMs) {
          count++;
        }
      }
      return count;
    },

    clear() {
      cache.clear();
    },
  };
}

