  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ 
    listener: Listener; 
    isOnce: boolean; 
  }>>();

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const eventListeners = listeners.get(event)!;
      eventListeners.push({
        listener,
        isOnce: false
      });
      return eventListeners.length;
    },

    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const eventListeners = listeners.get(event)!;
      eventListeners.push({
        listener,
        isOnce: true
      });
      return eventListeners.length;
    },

    off(event, listener) {
      if (!listeners.has(event)) {
        return false;
      }
      const eventListeners = listeners.get(event)!;
      const index = eventListeners.findIndex(item => item.listener === listener);
      if (index === -1) {
        return false;
      }
      eventListeners.splice(index, 1);
      return true;
    },

    emit(event, payload) {
      if (!listeners.has(event)) {
        return [];
      }
      const eventListeners = listeners.get(event)!;
      const results: unknown[] = [];
      const indicesToRemove: number[] = [];

      for (let i = 0; i < eventListeners.length; i++) {
        const wrapper = eventListeners[i];
        results.push(wrapper.listener(payload));
        if (wrapper.isOnce) {
          indicesToRemove.push(i);
        }
      }

      for (let i = indicesToRemove.length - 1; i >= 0; i--) {
        eventListeners.splice(indicesToRemove[i], 1);
      }

      return results;
    },

    listenerCount(event) {
      if (!listeners.has(event)) {
        return 0;
      }
      return listeners.get(event)!.length;
    }
  };
}
