interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<
    string,
    { windowStart: number; count: number }
  >();

  function getWindowState(
    key: string,
    nowMs: number
  ): { windowStart: number; count: number } {
    const existing = state.get(key);
    if (existing && nowMs - existing.windowStart >= windowMs) {
      return { windowStart: nowMs, count: 0 };
    }
    if (!existing) {
      return { windowStart: nowMs, count: 0 };
    }
    return existing;
  }

  function updateWindowState(
    key: string,
    stateObj: { windowStart: number; count: number }
  ): void {
    state.set(key, stateObj);
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const windowState = getWindowState(key, nowMs);
      if (windowState.count < limit) {
        windowState.count++;
        updateWindowState(key, windowState);
        return true;
      }
      updateWindowState(key, windowState);
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const windowState = getWindowState(key, nowMs);
      const remaining = limit - windowState.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}
