type ListenerPayload<T> = (payload: T) => R;
type EventDispatcher<T = any> = {
    on: (event: string, listener: ListenerPayload<T>) => number;
    once: (event: string, listener: ListenerPayload<T>) => number;
    off: (event: string, listener: ListenerPayload<T>) => boolean;
    emit: (event: string, payload?: T) => R[];
    listenerCount: (event: string) => number;
};

interface ListenerInfo<T> {
    callback: (payload: T) => any;
    isOnce: boolean;
    handlerId: symbol;
}

type EventStore<T> = {
    normal: ListenerInfo<T>[];
    single: ListenerInfo<T>[];
};

function createEventEmitter<T = any>(): EventDispatcher<T> {
    const events = new Map<string, EventStore<T>>();
    let globalListenerId = 0;

    const getStore = (event: string): EventStore<T> => {
        if (!events.has(event)) {
            events.set(event, { normal: [], single: [] });
        }
        return events.get(event)!;
    };

    return {
        on: (event: string, listener: ListenerPayload<T>): number => {
            const store = getStore(event);
            const id = Symbol("listener");
            store.normal.push({ callback: listener, isOnce: false, handlerId: id });
            return store.normal.length;
