export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, { listeners: Array<{ listener: Listener, isOnce: boolean; }> , count: number}>();

  const getOrCreateEventState = (event: string): { listeners: Array<{ listener: Listener, isOnce: boolean; }>; count: number } => {
    if (!listeners.has(event)) {
      listeners.set(event, { listeners: [], count: 0 });
    }
    return listeners.get(event)!;
  };

  return {
    on(event: string, listener: Listener): number {
      const state = getOrCreateEventState(event);
      const newListener = { listener, isOnce: false };
      state.listeners.push(newListener);
      state.count += 1;
      return state.count;
    },
    once(event: string, listener: Listener): number {
      const state = getOrCreateEventState(event);
      const newListener = { listener, isOnce: true };
      state.listeners.push(newListener);
      state.count += 1;
      return state.count;
    },
    off(event: string, listener: Listener): boolean {
      const state = listeners.get(event);
      if (!state) {
        return false;
      }

      let initialCount = state.count;

      // Filter out the first matching listener instance.
      // This handles the requirement to remove only one matching registration.
      state.listeners = state.listeners.filter(item => {
          if (item.listener === listener) {
              // This is the one to remove (conceptually, we just skip it in the new array)
              return false; 
          }
          return true;
      });

      const newCount = state.listeners.length;

      const wasRemoved = newCount < initialCount;

      // If no listeners remain, clean up map entry for potential garbage collection optimization
      if (newCount === 0) {
          listeners.delete(event);
      }

      return wasRemoved;
    },
    emit(event: string, payload: unknown): unknown[] {
      const state = listeners.get(event);
      if (!state || state.listeners.length === 0) {
        return [];
      }

      const invocationResults: unknown[] = [];
      const listenersToProcess: { listener: Listener, isOnce: boolean; }[] = [...state.listeners];

      // Clone listeners to safely remove once listeners during iteration

      // Process in order
      for (const item of listenersToProcess) {
          let processed = false; // Flag to check if removal happened

          try {
              // Execute the listener
              const result = item.listener(payload);
              invocationResults.push(result);
              processed = true;
          } catch (e) {
              // In a real implementation, we might capture errors, but per contract we just invoke.
              // Here we just record that an invocation happened.
              invocationResults.push(undefined as any); // Simulate return value handling
          }

