export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;

  // Map to store state: key -> { count: number, windowStartMs: number }
  const keyStates = new Map<string, { count: number, windowStartMs: number }>();

  const getOrCreateKey = (key: string): { count: number, windowStartMs: number } => {
    if (!keyStates.has(key)) {
      keyStates.set(key, { count: 0, windowStartMs: 0 });
    }
    return keyStates.get(key)!;
  };

  const checkAndAdvanceWindow = (key: string, nowMs: number): { count: number, windowStartMs: number } & { isNewWindow: boolean } => {
    let state = getOrCreateKey(key);

    // Boundary reset rule: if nowMs - windowStart >= WINDOW_MS, start a fresh window
    const isNewWindow = (nowMs - state.windowStartMs) >= WINDOW_MS;

    if (isNewWindow) {
      state = { count: 1, windowStartMs: nowMs };
      keyStates.set(key, state);
    } else {
      // Still within the current window, just increment count
      state.count += 1;
      keyStates.set(key, state);
    }

    return { ...state, isNewWindow };
  };

  const allow = (key: string, nowMs: number): boolean => {
    const state = getOrCreateKey(key);

    const { isNewWindow } = checkAndAdvanceWindow(key, nowMs);

    if (isNewWindow) {
      // First call in a new window
      return 1 <= LIMIT;
    }

    if (state.count <= LIMIT) {
      // Still within limit in the current window
      return true;
    }

    // Reached limit or over limit in current window
    return false;
  };

  const remaining = (key: string, nowMs: number): number => {
    if (!keyStates.has(key)) {
      return LIMIT;
    }

    const state = keyStates.get(key)!;

    // If the window has reset due to time, return the full limit.
    if ((nowMs - state.windowStartMs) >= WINDOW_MS) {
        return LIMIT;
    }

    // Otherwise, return the current used count (or limit if count was somehow corrupted, but we rely on fixed logic)
    return Math.max(0, LIMIT - state.count);
  };

  const reset = (key: string): void => {
    keyStates.delete(key);
  };

  return {
    allow,
    remaining,
    reset
  };
}

