export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  // Internal structure stored in the Map value
  interface CacheEntry {
    value: unknown;
    expiresAt: number;
    isDeleted: boolean;
  }

  const cache = new Map<string>();
  const DEFAULT_TTL = 1000;

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const actualTtlMs = ttlMs === undefined ? DEFAULT_TTL : ttlMs;
    const expiresAt = nowMs + actualTtlMs;

    cache.set(key, { value, expiresAt, isDeleted: false } as CacheEntry);
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key) as CacheEntry | undefined;
    if (!entry || entry.isDeleted) {
      return undefined;
    }
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return undefined;
    }
    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key) as CacheEntry | undefined;
    if (!entry || entry.isDeleted) {
      return false;
    }
    return nowMs < entry.expiresAt;
  };

  const delete = (key: string): boolean => {
    const entry = cache.get(key) as CacheEntry | undefined;
    if (entry && !entry.isDeleted) {
      // Mark as deleted instead of outright removing to allow size/existence checks
      cache.set(key, { value: undefined as unknown, expiresAt: entry.expiresAt, isDeleted: true } as CacheEntry);
      return true;
    }
    return false;
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const entry of cache.values()) {
      if (!entry.isDeleted && nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear = (): void => {
    cache.clear();
  };

  return {
    set,
    get,
    has,
    delete,
    size,
    clear
  };
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL_MS = 1000;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      let expiresAt: number;

      if (ttlMs === undefined) {
        // Use fixed default TTL
        expiresAt = nowMs + DEFAULT_TTL_MS;
      } else if (ttlMs === 0) {
        // Immediate expiration
        expiresAt = nowMs;
      } else if (Number.isFinite(ttlMs) && ttlMs > 0) {
        // Explicit positive TTL
        expiresAt = nowMs + ttlMs;
      } else {
        // Handle invalid/negative TTL by setting short TTL or throwing (here, we'll set a default short one)
        expiresAt = nowMs + DEFAULT_TTL_MS;
      }

      cache.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        this.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) {
        return false;
      }
      return nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      if (cache.has(key)) {
        cache.delete(key);
        return true;
      }
      return false;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const entry of cache.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      cache.clear();
    }
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

