export function createEventEmitter() {
  const listeners = new Map<string, Array<{ listener: (...args: any[]) => void, isOnce: boolean }>>({});

  const on = (event: string, listener: (...args: any[]) => void): number => {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const eventListeners = listeners.get(event)!;
    eventListeners.push({ listener, isOnce: false });
    return eventListeners.length;
  };

  const once = (event: string, listener: (...args: any[]) => void): number => {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const eventListeners = listeners.get(event)!;
    eventListeners.push({ listener, isOnce: true });
    return eventListeners.length;
  };

  const off = (event: string, listener: (...args: any[]) => void): boolean => {
    if (!listeners.has(event)) {
      return false;
    }
    const eventListeners = listeners.get(event)!;
    const initialLength = eventListeners.length;

    const filteredListeners = eventListeners.filter(item => 
      !(item.listener === listener && !item.isOnce)
    );

    if (filteredListeners.length < initialLength) {
      listeners.set(event, filteredListeners);
      return true;
    }
    return false;
  };

  const listenerCount = (event: string): number => {
    return listeners.has(event) ? listeners.get(event)!.length : 0;
  };

  const emit = (event: string, ...args: any[]): any[] => {
    if (!listeners.has(event)) {
      return [];
    }
    const eventListeners = listeners.get(event)!;
    const results: any[] = [];

    for (const item of eventListeners) {
      if (!item.isOnce) {
        results.push(item.listener(...args));
      }
    }

    return results;
  };

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
