export function createEventEmitter(): EventEmitter {
  const listeners: { [event: string]: { listeners: Listener[], onceListeners: { [listener: Listener]: void } } } = {};

  interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
  }

  const addListener = (event: string, listener: Listener, once: boolean = false) => {
    if (!listeners[event]) {
      listeners[event] = { listeners: [], onceListeners: {} };
    }

    if (once) {
      if (listeners[event].onceListeners[listener]) {
        return;
      }
      listeners[event].onceListeners[listener] = true;
    } else {
      listeners[event].listeners.push(listener);
    }
  };

  const removeListener = (event: string, listener: Listener): boolean => {
    if (!listeners[event]) {
      return false;
    }

    if (listeners[event].onceListeners[listener]) {
      delete listeners[event].onceListeners[listener];
      return true;
    }

    const index = listeners[event].listeners.indexOf(listener);
    if (index !== -1) {
      listeners[event].listeners.splice(index, 1);
      return true;
    }

    return false;
  };

  const emitListeners = (event: string, payload: unknown): unknown[] => {
    const results: unknown[] = [];
    if (!listeners[event]) {
      return results;
    }

    const eventData = listeners[event];

    // Emit 'once' listeners first, in registration order
    for (const listener of eventData.listeners) {
      if (eventData.onceListeners[listener]) {
        const result = listener(payload);
        results.push(result);
        delete eventData.onceListeners[listener];
      }
    }

    // Emit regular listeners in registration order
    for (const listener of eventData.listeners) {
      const result = listener(payload);
      results.push(result);
    }

    return results;
  };

  const listenerCount = (event: string): number => {
    if (!listeners[event]) {
      return 0;
    }
    return listeners[event].listeners.length + Object.keys(listeners[event].onceListeners).length;
  };

  return {
    on: (event: string, listener: Listener): number => {
      addListener(event, listener, false);
      return listenerCount(event);
    },
    once: (event: string, listener: Listener): number => {
      addListener(event, listener, true);
      return listenerCount(event);
    },
    off: (event: string, listener: Listener): boolean => {
      return removeListener(event, listener);
    },
    emit: (event: string, payload: unknown): unknown[] => {
      return emitListeners(event, payload);
    },
    listenerCount: listenerCount,
  };
}

export function createRateLimiter(key: string): { allow: (key: string, nowMs: number) => void, remaining: (key: string, nowMs: number) => number, reset: (key: string) => void } {
  const requestTimestamps: { [key: string]: number[] } = {};
  const WINDOW_MS = 1000;
  const MAX_REQUESTS = 3;

  const recordRequest = (key: string, nowMs: number): boolean => {
    if (!requestTimestamps[key]) {
      requestTimestamps[key] = [];
    }

    let timestamps = requestTimestamps[key];
    const windowStartMs = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;

    // Clean up old timestamps outside the current window
    timestamps = timestamps.filter(ts => ts >= windowStartMs);
    requestTimestamps[key] = timestamps;

    if (timestamps.length < MAX_REQUESTS) {
      timestamps.push(nowMs);
      return true;
    }

    return false;
  };

  const getRemaining = (key: string, nowMs: number): number => {
    if (!requestTimestamps[key]) {
      return MAX_REQUESTS;
    }

    let timestamps = requestTimestamps[key];
    const windowStartMs = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;

    // Clean up old timestamps outside the current window
    timestamps = timestamps.filter(ts => ts >= windowStartMs);
    requestTimestamps[key] = timestamps;

    const currentWindowCount = timestamps.length;
    if (currentWindowCount < MAX_REQUESTS) {
      return MAX_REQUESTS - currentWindowCount;
    }

    return 0;
  };

  const clearKey = (key: string): void => {
    delete requestTimestamps[key];
  };

  return {
    allow: (key: string, nowMs: number): void => {
      if (recordRequest(key, nowMs)) {
        // Allowed
      } else {
        // Not allowed
      }
    },
    remaining: (key: string, nowMs: number): number => {
      return getRemaining(key, nowMs);
    },
    reset: (key: string): void => {
      clearKey(key);
    }
  };
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const state = new Map<string, {
    windowStart: number;
    remaining: number;
  }>();

  const allow = (key: string, nowMs: number): boolean => {
    const keyState = state.get(key);

    if (!keyState) {
      state.set(key, {
        windowStart: nowMs,
        remaining: limit,
      });
      return true;
    }

    if (nowMs - keyState.windowStart >= windowMs) {
      keyState.windowStart = nowMs;
      keyState.remaining = limit;
      return true;
    }

    if (keyState.remaining > 0) {
      keyState.remaining--;
      return true;
    }

    return false;
  };

  const remaining = (key: string, nowMs: number): number => {
    const keyState = state.get(key);
    if (!keyState) {
      return limit;
    }
    if (nowMs - keyState.windowStart >= windowMs) {
      return limit;
    }
    return keyState.remaining;
  };

  const reset = (key: string): void => {
    state.delete(key);
  };

  return {
    allow,
    remaining,
    reset,
  } as RateLimiter;
}

