export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, {
    value: unknown,
    expiresAt: number
  }>();

  const defaultTtlMs = 1000;

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const ttl = ttlMs !== undefined ? ttlMs : defaultTtlMs;
    const expiresAt = nowMs + ttl;
    cache.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key);
    if (!entry) {
      return undefined;
    }
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return undefined;
    }
    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key);
    if (!entry) {
      return false;
    }
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return false;
    }
    return true;
  };

  const deleteKey = (key: string): boolean => {
    if (!cache.has(key)) {
      return false;
    }
    cache.delete(key);
    return true;
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const [key, entry] of cache.entries()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear = (): void => {
    cache.clear();
  };

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown, expiresAt: number, ttlMs: number }>();
  const DEFAULT_TTL = 1000;

  function isExpired(expiresAt: number, nowMs: number): boolean {
    return nowMs >= expiresAt;
  }

  function cleanExpired(nowMs: number): void {
    for (const [key, entry] of cache.entries()) {
      if (isExpired(entry.expiresAt, nowMs)) {
        cache.delete(key);
      }
    }
  }

  function getEntry(key: string): MapEntry | undefined {
    const entry = cache.get(key);
    if (entry && isExpired(entry.expiresAt, nowMs)) {
      cache.delete(key);
      return undefined;
    }
    return entry;
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const effectiveTtlMs = ttlMs === undefined ? DEFAULT_TTL : ttlMs;
      const expiresAt = nowMs + effectiveTtlMs;

      const entry = cache.get(key);

      // If there is an existing entry, delete it to ensure the new one starts fresh 
      // based on the current time and new TTL. This handles set overwriting and refreshing.
      if (entry) {
        cache.delete(key);
      }

      cache.set(key, { value, expiresAt, ttlMs: effectiveTtlMs });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) {
        return false;
      }
      return !isExpired(entry.expiresAt, nowMs);
    },

    delete(key: string): boolean {
      const wasDeleted = cache.delete(key);
      return wasDeleted;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const entry of cache.values()) {
        if (!isExpired(entry.expiresAt, nowMs)) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      cache.clear();
    }
  };
}

