    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    listeners.get(event)!.push(listener);
    if (!onceMap.has(event)) {
      onceMap.set(event, true);
      onceListeners.set(event, []);
    }
    onceListeners.get(event)!.push(listener);
    return listeners.get(event)!.length + (onceMap.get(event)! ? onceListeners.get(event)!.length : 0);
  }

  function off(event: string, listener: Listener): boolean {
    const eventListeners = listeners.get(event);
    if (eventListeners) {
      const index = eventListeners.indexOf(listener);
      if (index !== -1) {
        eventListeners.splice(index, 1);
        return true;
      }
    }
    const onceEventListeners = onceListeners.get(event);
    if (onceEventListeners) {
