function createEventEmitter(): EventEmitter {
  const listeners: Map<string, Set<Listener>> = new Map()
  const onceListeners: Map<string, Array<Listener>> = new Map()

  function ensureListeners(event: string) {
    if (!listeners.has(event)) {
      listeners.set(event, new Set())
    }
    if (!onceListeners.has(event)) {
      onceListeners.set(event, [])
    }
  }

  return {
    on(event: string, listener: Listener): number {
      ensureListeners(event)
      const set = listeners.get(event)!
      set.add(listener)
      return set.size
    },

    once(event: string, listener: Listener): number {
      ensureListeners(event)
      const onceList = onceListeners.get(event)!
      onceList.push(listener)
      const set = listeners.get(event)!
      set.add(listener)
      return set.size
    },

    off(event: string, listener: Listener): boolean {
      const set = listeners.get(event)
      if (set) {
        if (set.delete(listener)) {
          const onceList = onceListeners.get(event)
          if (onceList) {
            const idx = onceList.indexOf(listener)
            if (idx >= 0) {
              onceList.splice(idx, 1)
            }
          }
          return true
        }
      }
      return false
    },

    emit(event: string, payload: unknown): unknown[] {
      const results: unknown[] = []
      const set = listeners.get(event)
      if (set) {
        for (const listener of set) {
          results.push(listener(payload))
        }
      }
      const onceList = onceListeners.get(event)
      if (onceList) {
        for (const listener of onceList) {
          results.push(listener(payload))
        }
        onceListeners.set(event, [])
      }
      return results
    },

    listenerCount(event: string): number {
      const set = listeners.get(event)
      const onceList = onceListeners.get(event)
      return (set?.size ?? 0) + (onceList?.length ?? 0)
    }
  }
