interface RateLimiterState {
  windowStart: number;
  count: number;
}

type RateLimiter = {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
};

interface RateLimiterConfig {
  maxRequests: number;
  windowMs: number;
}

function createRateLimiter(config: RateLimiterConfig = { maxRequests: 3, windowMs: 1000 }): RateLimiter {
  const state = new Map<string, RateLimiterState>();

  const getAndResetIfExpired = (key: string, nowMs: number): RateLimiterState => {
    const existing = state.get(key);
    if (!existing || nowMs >= existing.windowStart + config.windowMs) {
      return { windowStart: nowMs, count: 0 };
    }
    return existing;
  };

  const allow = (key: string, nowMs: number): boolean => {
    const data = getAndResetIfExpired(key, nowMs);
    if (data.count < config.maxRequests) {
      data.count += 1;
      state.set(key, data);
      return true;
    }
    return false;
  };

  const remaining = (key: string, nowMs: number): number => {
    const data = getAndResetIfExpired(key, nowMs);
    const result = config.maxRequests - data.count;
    return result < 0 ? 0 : result;
  };

  const reset = (key: string): void => {
    state.delete(key);
  };

  return { allow, remaining, reset };
}

export { createRateLimiter };
