export function createTtlCache() {
  const store = new Map<
    string,
    { value: unknown; expiresAt: number }
  >();

  const DEFAULT_TTL_MS = 1000;

  function set(
    key: string,
    value: unknown,
    nowMs: number,
    ttlMs?: number
  ): void {
    const expiresAt = nowMs + (ttlMs ?? DEFAULT_TTL_MS);
    store.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const entry = store.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = store.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  }

  function deleteKey(key: string): boolean {
    return store.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    const keysToDelete: string[] = [];
    for (const [k, e] of store.entries()) {
      if (nowMs >= e.expiresAt) {
        keysToDelete.push(k);
      } else {
        count++;
      }
    }
    for (const k of keysToDelete) {
      store.delete(k);
    }
    return count;
  }

  function clear(): void {
    store.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

const DEFAULT_TTL_MS = 1000

export function createTtlCache(): TtlCache {
  type Entry = { value: unknown; expiresAt: number }

  const store = new Map<string, Entry>()

  function purgeIfExpired(key: string, nowMs: number): boolean {
    const entry = store.get(key)
    if (!entry) return false
    if (nowMs >= entry.expiresAt) {
      store.delete(key)
      return false
    }
    return true
  }

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs ?? DEFAULT_TTL_MS
      const expiresAt = nowMs + ttl
      store.set(key, { value, expiresAt })
    },
    get(key, nowMs) {
      if (!purgeIfExpired(key, nowMs)) return undefined
      return store.get(key)!.value
    },
    has(key, nowMs) {
      return purgeIfExpired(key, nowMs)
    },
    delete(key) {
      return store.delete(key)
    },
    size(nowMs) {
      let count = 0
      for (const [k, entry] of store.entries()) {
        if (nowMs >= entry.expiresAt) {
          store.delete(k)
        } else {
          count++
        }
      }
      return count
    },
    clear() {
      store.clear()
    },
  }
}

