export function createEventEmitter(): EventEmitter {
  const listenersMap: Map<string, Array<{ fn: Listener; once: boolean }>> = new Map();

  return {
    on(event: string, listener: Listener): number {
      if (!listenersMap.has(event)) {
        listeners .set(event, []);
      }
      const eventListeners = listenersMap.get(event)!;
      eventListeners.push({ fn: listener, once: false });
      return eventListeners.length;
    },

    once(event: string, listener: Listener): number {
      if (!listenersMap.has(event)) {
        listenersMap.set(event, []);
      }
      const eventListeners = listenersMap.get(event)!;
      eventListeners.push({ fn: listener, once: true });
      return eventListeners.length;
    },

    off(event: string, listener: Listener): boolean {
      const eventListeners = listenersMap.get(event);
      if (!eventListeners) return false;

      for (let i = 0; i < eventListeners.length; i++) {
        if (eventListeners[i].fn === listener) {
          eventListeners.splice(i, 1);
          if (eventListeners.length === 0) {
            listenersMap.delete(event);
          }
          return true;
        }
      }
      return false;
    },

    emit(event: string, payload: any): any[] {
      const eventListeners = listenersMap.get(event);
      if (!eventListeners) return [];

      const results: any[] = [];
      const toRemove: number[] = [];

      // Iterate over a copy to prevent issues if listeners are removed during execution
      const snapshot = [...eventListeners];

      for (const entry of snapshot) {
        results.push(entry.fn(payload));
        if (entry.once) {
          toRemove.push(eventListeners.indexOf(entry));
        }
      }

      // Handle cleanup for 'once' listeners in reverse order to maintain correct indices
      for (let i = toRemove.length - 1; i >= 0; i--) {
        const index = toRemove[i];
        if (index !== -1) {
          eventListeners.splice(index, 1);
        }
      }

      if (eventListeners.length === 0) {
        listenersMap.delete(event);
      }

      return results;
    },

    listenerCount(event: string): number {
      return listenersMap.get(event)?.length ?? 0;
    }
  };
}
