interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

interface KeyState {
  windowStart: number
  count: number
}

export function createRateLimiter(): RateLimister {
  const states = new Map<string, KeyState>()
  const limit = 3
  const windowMs = 1000

  function getOrUpdateState(key: string, nowMs: number): KeyState {
    let state = states.get(key)

    if (!state || (nowMs - state.windowStart >= windowMs)) {
      state = {
        windowStart: nowMs,
        count: 0
      }
      states.set(key, state)
    }

    return state
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrUpdateState(key, nowMs)
      if (state.count < limit) {
        state.count++
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      const state = states.get(key)
      if (!state || (nowMs - state.windowStart >= windowMs)) {
        // If window expired, the next 'allow' or 'remaining' call would effectively use a new window
        // But for the current state, if we are checking 'remaining' and it's expired, we return the limit
        return limit
      }
      return Math.max(0, limit - state.count)
    },

    reset(key: string): void {
      states.delete(key)
    }
  }
}
