  expiresAt: number;
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, CacheEntry>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      cache.set(key, {
        value,
        expiresAt: nowMs + ttlMs,
      });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (entry === undefined || nowMs >= entry.expiresAt) {
        if (entry !== undefined && nowMs >= entry.expiresAt) {
          cache.delete(key);
        }
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (entry === undefined) {
        return false;
      }
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return cache.delete(key);
    },

    size(nowMs: number): number {
      let liveCount = 0;
      for (const entry of cache.values()) {
        if (nowMs < entry.expiresAt) {
          liveCount++;
        }
      }
      // Note: Although we don't mutate the map during size() to avoid side effects
      // unexpected by other concurrent logic, this ensures the return value
      // is strictly deterministic based on the provided nowMs.
      return liveCount;
    },

    clear(): void {
      cache.clear();
    },
  };
}
