type Listener<T = unknown> = (payload: T) => unknown;

interface EventEmitter<T = unknown> {
  on<V = T>(event: string, listener: Listener<V>): number;
  once<V = T>(event: string, listener: Listener<V>): number;
  off<V = T>(event: string, listener: Listener<V>): boolean;
  emit<V = T>(event: string, payload?: V): unknown[];
  listenerCount(event: string): number;
}

interface OneTimeListener<T = unknown> {
  (payload: T): unknown;
  _once: true;
}

function createEventEmitter(): EventEmitter<unknown> {
  const listeners = new Map<string, Array<Listener>>();

  function on<V = unknown>(event: string, listener: Listener<V>): number {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const eventListeners = listeners.get(event)!;
    eventListeners.push(listener as Listener);
    return eventListeners.length;
  }

  function once<V = unknown>(event: string, listener: Listener<V>): number {
    const oneTimeListener: Listener = function (this: unknown, payload) {
      off(event, oneTimeListener as Listener);
      return (listener as Function).call(this, payload);
    };
    (oneTimeListener as OneTimeListener)._once = true;
    return on(event, oneTimeListener);
  }

  function off<V = unknown>(event: string, listener: Listener<V>): boolean {
    const eventListeners = listeners.get(event);
    if (!eventListeners || eventListeners.length === 0) {
      return false;
    }
    const index = eventListeners.indexOf(listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
      return true;
    }
    return false;
  }

  function emit<V = unknown>(event: string, payload?: V): unknown[] {
    const eventListeners = listeners.get(event);
    if (!eventListeners) {
      return [];
    }
    const results: unknown[] = [];
    for (const listener of eventListeners) {
      results.push(listener(payload));
    }
    return results;
  }

  function listenerCount(event: string): number {
    const eventListeners = listeners.get(event);
    return eventListeners ? eventListeners.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

export { createEventEmitter };
