export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  const state = new Map<string, { windowStart: number; count: number }>();

  function allow(key: string, nowMs: number): boolean {
    const windowEnd = nowMs - WINDOW_MS;
    let entry = state.get(key);

    if (!entry || entry.windowStart <= windowEnd) {
      entry = { windowStart: nowMs, count: 1 };
      state.set(key, entry);
      return true;
    }

    if (entry.count < MAX_REQUESTS) {
      entry.count++;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const windowEnd = nowMs - WINDOW_MS;
    const entry = state.get(key);

    if (!entry || entry.windowStart <= windowEnd) {
      return MAX_REQUESTS;
    }

    const used = entry.count;
    const result = MAX_REQUESTS - used;
    return result < 0 ? 0 : result;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}
